#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;long long target;scanf("%d %lld",&n,&target);
vector<long long>a(n);for(int i=0;i<n;++i)scanf("%lld",&a[i]);
int left=0,best=1e9;long long s=0;
for(int right=0;right<n;++right){s+=a[right];
while(s>=target){best=min(best,right-left+1);s-=a[left++];}}
printf("%d\n",best==1e9?0:best);return 0;}

